<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesRoleVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;

trait PlatformIdentityRolesRoleAttributeHolder
{
    protected PlatformIdentityRolesRoleVO|RoleRef|null $role = null;
    protected bool $roleAssigned = false;

    public function getRoleOrDefault(?PlatformIdentityRolesRoleVO $role): ?PlatformIdentityRolesRoleVO
    {
        return $this->roleAssigned ? ($this->role !== null ? PlatformIdentityRolesRoleVO::from($this->role) : null) : $role;
    }
    public function role(PlatformIdentityRolesRoleVO|RoleRef|null $role): static
    {
        $this->role = $role;
        $this->roleAssigned = true;
        return $this;
    }
    public function getRole(): ?RoleRef
    {
        return is_a($this->role, PlatformIdentityRolesRoleVO::class) ? $this->role?->value() : $this->role;
    }
    public function unsetRole(): static
    {
        $this->role = null;
        $this->roleAssigned = false;
        return $this;
    }
    protected function withDefaultRole(): void
    {
    }
    protected function withAssertedRoleRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->roleAssigned = $this->roleAssigned) {
            $value->role = PlatformIdentityRolesRoleVO::tryFrom($this->role, $errorsList);
        }
    }
}
